import { expect, expectStatus, test } from "../../fixtures";

test("An unparseable insurance expiry date is extracted as null with low confidence", { tag: "@DOC-03" }, async ({ apiAs, factory }) => {
  // Arrange
  const member = await apiAs("member");
  const vendor = await factory.vendor();
  expect(vendor.status, "the vendor starts as a draft").toBe("draft");
  // This sample's expiry line reads "Expiry Date: next spring".
  const document = await factory.upload(vendor.id, "insurance_certificate", "insurance_certificate_unparseable.txt");

  // Act
  await expect
    .poll(
      async () => (await expectStatus<{ status: string }>(await member.get(`/api/documents/${document.id}`), 200)).status,
      { message: "processing finishes for the insurance certificate", timeout: 30_000 },
    )
    .toBe("extracted");

  // Assert
  const extraction = await expectStatus<{ fields: Record<string, { value: string | null; confidence: number }> }>(
    await member.get(`/api/documents/${document.id}/extraction`),
    200,
  );
  expect(extraction.fields.expiry_date, JSON.stringify(extraction.fields)).toBeDefined();
  expect(extraction.fields.expiry_date.value).toBeNull();
  expect(extraction.fields.expiry_date.confidence).toBeLessThan(0.5);
});
